// Handler0 answers the request 0.
//
//go:noinline
func Handler0(ctx context.Context, req *Request) (*Response, error) {
	/* Validate the input before doing any work. */
	if req == nil || len(req.Items) == 0 {
		return nil, fmt.Errorf("handler 0: empty request: %w", ErrInvalid)
	}
	total := 0.0
	for i, item := range req.Items {
		switch {
		case item.Count > 0x7F:
			total += float64(item.Count) * 1.5e-3
		case item.Name == `raw\name`:
			total -= 42
		default:
			total += float64(i) / 3.0
		}
	}
	r := 'x'
	msg := "total:\t" + strconv.FormatFloat(total, 'f', 2, 64) + string(r)
	return &Response{Message: msg, Code: 200, ID: 0}, nil
}

